import {
    type ConfigurationChangeEvent,
    type CancellationToken
} from 'vscode';
import type Scope from '../Scope/Scope';
import type Snapshot from './Snapshot';


/** ProjectSpace — адаптер над VS Code workspace API, изолирующий доменную модель
 * расширения от деталей платформы и предоставляющий структуру рабочего
 * пространства в терминах областей-источников задач.
 *
 * ## Концептуальная роль
 *
 * VS Code workspace — это низкоуровневая платформенная конструкция: набор папок,
 * конфигурационных файлов и событий. `ProjectSpace` переводит эту конструкцию
 * в доменный язык расширения: набор `Scope`-объектов, каждый из которых
 * представляет самостоятельный источник задач, и `Snapshot`-объект, содержащий
 * актуальные данные по этим источникам.
 *
 * Интерфейс намеренно не знает о конкретном происхождении областей (папки
 * рабочего пространства, пользовательские пути, виртуальные FS и т. д.) — это детали
 * реализующего класса.
 *
 * ## Зоны ответственности
 *
 * - Определить, **какие области** структурно присутствуют в рабочем пространстве.
 * - Определить, **нужно ли пересобирать** снимок при изменении конфигурации.
 * - **Построить снимок** — выполнить сбор данных по переданным областям.
 *
 * ## Чем не занимается
 *
 * - Не хранит состояние снимка — `Snapshot` живёт вне этого интерфейса.
 * - Не решает, когда именно запускать перестройку.
 * - Не фильтрует и не агрегирует задачи.
 *
 * ## Место в архитектуре
 *
 * ```
 * VS Code workspace API
 *        │
 *        ▼
 *  ProjectSpace       ← этот интерфейс (адаптер / anti-corruption layer)
 *        │
 *        ├── getScopes()      → [Scope, ...] обработка/фильтрация
 *        │                              │
 *        │                              ▼
 *        └──────────────────── buildSnapshot() → Snapshot
 *                                                   │
 *                                                   ▼
 *                                          TreeDataProvider / UI
 * ```
 * */
interface ProjectSpace {

    /** Возвращает текущий набор областей рабочего пространства.
     *
     * Каждый `Scope` представляет один источник задач:
     * - Глобальное пространство (@todo не реализовано)
     * - Рабочее пространство
     * - Директория рабочего пространства
     *
     * Актуальность данных определяется на момент
     * последнего обновления состояния реализующего класса.
     *
     * @returns Неизменяемый массив объектов `Scope`. Порядок элементов:
     *   - Глобальное пространство (если есть)
     *   - Рабочее пространство (если есть)
     *   - Директории рабочего пространства, в порядке предоставленном VS Code
     *   Массив может быть пустым.
     * */
    readonly getScopes: () => ReadonlyArray<Readonly<Scope>>;

    /** Определяет, должно ли изменение конфигурации VS Code повлечь
     * полную перестройку снимка.
     *
     * Вызывается в обработчике события `workspace.onDidChangeConfiguration`
     * до принятия решения о запуске `buildSnapshot`. Позволяет реализации
     * самостоятельно декларировать, какие ключи конфигурации для неё
     * значимы, не раскрывая эти детали вызывающему коду.
     *
     * @param event - Событие изменения конфигурации от VS Code.
     * @returns `true`, если изменение затрагивает данные, от которых
     *   зависит содержимое снимка, и снимок необходимо пересобрать.
     *   `false`, если изменение нерелевантно и пересборка не нужна.
     * */
    readonly shouldRebuildSnapshot: (event: ConfigurationChangeEvent) => boolean;

    /** Строит снимок данных по переданному набору областей.
     *
     * Реализация выполняет
     * чтение конфигурации, обращения к VS Code API и формирует
     * полное представление задач для каждой из переданных областей.
     *
     * Операция поддерживает отмену через `CancellationToken`. Реализация
     * выбросит `CancellationError`.
     *
     * Список `scopes` передаётся явно, чтобы вызывающий код мог контролировать,
     * для каких именно областей строится снимок.
     *
     * @param scopes - Области, по которым требуется собрать данные.
     *   Результат `getScopes()` или подмножество.
     * @param token - Токен отмены операции.
     * @returns Promise, разрешающийся в `Snapshot` с данными
     *   по всем переданным областям.
     */
    readonly buildSnapshot: (scopes: ReadonlyArray<Readonly<Scope>>, token: CancellationToken) => Promise<Snapshot>;
}


export default ProjectSpace;
